contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;

        require(balanceBefore >= minSum, "precondition: balance >= MinSum");
        require(collectAmount < balanceBefore, "precondition: collectAmount < balanceBefore");

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherAfter = address(c).balance;

        assert(!reverted && balanceAfter == balanceBefore - collectAmount && etherAfter == etherBefore - collectAmount);
    }

    receive() external payable {}
}

