pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount, uint256 collectAmount, uint256 minSum) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint etherBefore = address(c).balance;
        vm.assume(balanceBefore >= minSum);
        vm.assume(collectAmount < balanceBefore);
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint etherAfter = address(c).balance;
        assertTrue(!reverted && balanceAfter == balanceBefore - collectAmount && etherAfter == etherBefore - collectAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        _run(depositAmount, collectAmount, minSum);
    }

    receive() external payable {}
}
